def count_no_rl(n):
    import itertools
    count=0
    for bits in itertools.product('LR', repeat=n):
        ok=True
        for i in range(n-1):
            if bits[i]=='R' and bits[i+1]=='L':
                ok=False
                break
        if ok:
            count+=1
    return count

for n in range(1,10):
    print(n, count_no_rl(n))

